<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#123c52"><title>SIM Ma'had Aly</title><link rel="stylesheet" href="assets/style.css?v=<?=(int)@filemtime(dirname(__DIR__).'/assets/style.css')?>"><link rel="icon" type="image/png" href="assets/favicon.png"></head><body><header><a class="brand" href="?page=dashboard"><img src="assets/logo-mahad-aly.png" alt="Ma'had Aly Luqmanul Hakim" width="133" height="58" style="height:58px;width:auto;max-width:60vw"></a><nav aria-label="Menu utama"><?php foreach (['dashboard'=>'Dashboard','peserta'=>'Data Peserta','guru'=>'Data Guru','pengurus'=>'Data Pengurus','aset'=>'Aset','keuangan'=>'Keuangan','pengguna'=>'Pengguna','akun'=>'Akun','laporan'=>'Laporan'] as $key=>$label): if(can_view($key)): ?><a <?= $page===$key?'aria-current="page"':'' ?> href="?page=<?=esc($key)?>"><?=esc($label)?></a><?php endif;endforeach; ?></nav><form method="post"><?php token(); ?><button name="action" value="logout" class="logout">Keluar</button></form></header><main><p class="userchip">Masuk sebagai <b><?=esc($_SESSION['username'])?></b> <i><?=esc($_SESSION['role'])?></i></p><?php if(isset($_SESSION['flash'])): ?><div class="notice" role="status"><?=esc($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif; ?><?php try {require __DIR__.'/'.$page.'.php';} catch(Throwable $e) {error_log($e->getMessage());echo '<p class="error">Data belum dapat ditampilkan. Periksa konfigurasi database dan impor tabel sistem.</p>';} ?></main><footer>SIM Ma'had Aly Luqmanul Hakim</footer><script>document.querySelectorAll(".tablewrap table").forEach(function(t){var h=[].map.call(t.querySelectorAll("thead th"),function(x){return x.textContent.trim()});t.querySelectorAll("tbody tr").forEach(function(r){[].forEach.call(r.children,function(c,i){if(h[i]&&!c.hasAttribute("colspan"))c.setAttribute("data-label",h[i])})})})</script></body></html>
